	public static boolean requiresScope(QueryEvaluationStep step) {
		if (step instanceof ScopedEvaluationStep scoped) {
			return scoped.requiresScope;
		}
		return step != null && step.getClass() == JoinQueryEvaluationStep.class
				&& ((JoinQueryEvaluationStep) step).scopedDelegate() != null;
	}

	public static ScopedEvaluationStep adapt(TupleExpr expression, QueryEvaluationStep step) {
		if (step instanceof ScopedEvaluationStep scoped) {
			return scoped;
		}
		if (step != null && step.getClass() == JoinQueryEvaluationStep.class) {
			ScopedEvaluationStep scoped = ((JoinQueryEvaluationStep) step).scopedDelegate();
			if (scoped != null) {
				return scoped;
			}
		}
		return new ScopedEvaluationStep(expression, step, null, false);
	}

