	public static QueryEvaluationStep slice(Slice node, QueryEvaluationStep ordinary, QueryEvaluationStep child) {
		if (!needsScopedComposition(node) && !requiresScope(child)) {
			return ordinary;
		}
		ScopedEvaluationStep childStep = adapt(node.getArg(), child);
		return new ScopedEvaluationStep(node, ordinary, (owner, bindings, varyingNames) -> {
			QueryEvaluationStep scopedChild = input -> {
				return openChild(owner, childStep, node.getArg(), input, varyingNames);
			};
			if (owner.isProbeView()) {
				Set<String> unavailable = effectiveUnavailableNames(owner, bindings);
				boolean partialContext = !unavailable.isEmpty()
						&& (hasUnavailableServiceDependency(node.getArg(), unavailable)
								|| !QueryEvaluationUtility.permitsBindingInjection(node.getArg(), unavailable)
								|| QueryEvaluationUtility.usesMappingParameterizedEvaluation(node.getArg(),
										unavailable));
				if (!partialContext) {
					ScopedEvaluationOwner normalOwner = owner.normalView();
					AtomicReference<CloseableIteration<BindingSet>> source = new AtomicReference<>();
					QueryEvaluationStep normalChild = input -> {
						if (normalOwner.isClosed()) {
							return QueryEvaluationStep.EMPTY_ITERATION;
						}
						CloseableIteration<BindingSet> opened = childStep.evaluateScoped(normalOwner, input,
								varyingNames);
						source.set(opened);
						return opened;
					};
					CloseableIteration<BindingSet> result = SliceQueryEvaluationStep.supply(node, normalChild)
							.evaluate(bindings);
					return preserveProbeAvailability(result, owner, source.get(), varyingNames, false,
							declaredAvailability(node.getArg()));
				}
				CloseableIteration<BindingSet> probeSource = scopedChild.evaluate(bindings);
				boolean sourceOwned = true;
				try {
					// A partial child may already expose a row, but applying OFFSET/LIMIT to that prefix would publish
					// a
					// derived row before the blocked sibling has established completion. Drive only the child's bounded
					// preflight; do not construct the Slice iterator until the child is known complete.
					probeSource.hasNext();
					if (ScopedEvaluationStep.probeCompletion(probeSource) == Completion.BLOCKED) {
						Throwable closeFailure = closeIteration(probeSource, null);
						sourceOwned = false;
						if (closeFailure != null) {
							throwAsUnchecked(closeFailure);
						}
						return blockedProbe();
					}
					CloseableIteration<BindingSet> result = SliceQueryEvaluationStep.supply(node, input -> probeSource)
							.evaluate(bindings);
					sourceOwned = false;
					return new ScopedProbeCompletionGate(result,
							() -> ScopedEvaluationStep.probeCompletion(probeSource), true);
				} catch (Throwable failure) {
					if (sourceOwned) {
						failure = closeIteration(probeSource, failure);
					}
					throwAsUnchecked(failure);
					return QueryEvaluationStep.EMPTY_ITERATION;
				}
			}
			CloseableIteration<BindingSet> result = SliceQueryEvaluationStep.supply(node, scopedChild)
					.evaluate(bindings);
			return result;
		}, true);
	}

	public static QueryEvaluationStep distinct(Distinct node, QueryEvaluationStep ordinary, QueryEvaluationStep child,
			Supplier<CollectionFactory> collectionFactories) {
		if (!needsScopedComposition(node) && !requiresScope(child)) {
			return ordinary;
		}
		ScopedEvaluationStep childStep = adapt(node.getArg(), child);
		return new ScopedEvaluationStep(node, ordinary, (owner, bindings, varyingNames) -> {
			CollectionFactory collectionFactory = collectionFactories.get();
			CloseableIteration<BindingSet> source = null;
			try {
				source = openChild(owner, childStep, node.getArg(), bindings, varyingNames);
				CloseableIteration<BindingSet> openedSource = source;
				CloseableIteration<BindingSet> result = new DistinctIteration<>(source,
						collectionFactory.createSetOfBindingSets()) {
					@Override
					protected void handleClose() {
						try {
							collectionFactory.close();
						} finally {
							super.handleClose();
						}
					}
				};
				return owner.isProbeView()
						? new ScopedProbeCompletionGate(result,
								() -> ScopedEvaluationStep.probeCompletion(openedSource))
						: result;
			} catch (Throwable failure) {
				failure = closeIteration(source, failure);
				try {
					collectionFactory.close();
				} catch (Throwable closeFailure) {
					if (closeFailure != failure) {
						failure.addSuppressed(closeFailure);
					}
				}
				throwAsUnchecked(failure);
				return QueryEvaluationStep.EMPTY_ITERATION;
			}
		}, true);
	}

	public static QueryEvaluationStep distinct(Distinct node, QueryEvaluationStep child,
			Supplier<CollectionFactory> collectionFactories) {
		return distinct(node, QueryEvaluationStep.EMPTY, child, collectionFactories);
	}

